  /* Surface */
  --bg-base:     #FFFFFF;
  --bg-subtle:   #F7F8FA;
  --bg-elevated: #FFFFFF;
  --bg-overlay:  rgba(28,43,51,0.45);

  /* Text */
  --text-primary:    #1C2B33;
  --text-secondary:  #3A3B3C;
